    if f"### {category}" not in text:
        text = text.rstrip() + ("\n\n" if text.strip() else "") + f"### {category}\n"
    text = text.rstrip() + f"\n{entry}\n"
    log.parent.mkdir(parents=True, exist_ok=True)
    log.write_text(text, encoding="utf-8")


